54				t.Fatalf("item %d state = %s, want %s", i, snap.State, states[i])
55			}
56		}
57	
58		// Closed interval: both endpoints included.
59		got, err = s.ExportSnapshots(doc, 2, ptrInt64(3))
60		if err != nil {
61			t.Fatal(err)
62		}
63		if len(got) != 2 || got[0].Cursor != 2 || got[1].Cursor != 3 {
64			t.Fatalf("[2,3] = %+v", got)
65		}
66	
67		// A degenerate interval still includes the single matching cursor.
68		got, err = s.ExportSnapshots(doc, 2, ptrInt64(2))
69		if err != nil {
70			t.Fatal(err)
71		}
