79			t.Fatal(err)
80		}
81		if len(got) != 2 || got[0].Cursor != 3 || got[1].Cursor != 4 {
82			t.Fatalf("from=3 = %+v", got)
83		}
84	
85		// A range without a snapshot is an empty non-nil list, not an error.
86		got, err = s.ExportSnapshots(doc, 99, ptrInt64(200))
87		if err != nil {
88			t.Fatal(err)
89		}
90		if got == nil || len(got) != 0 {
91			t.Fatalf("empty range = %+v, want empty non-nil", got)
92		}
93	
94		// An unknown document is likewise an empty list.
95		got, err = s.ExportSnapshots("never-heard-of-it", 0, nil)
96		if err != nil {
97			t.Fatal(err)
98		}
99		if got == nil || len(got) != 0 {
