219		if err != nil {
220			t.Fatal(err)
221		}
222		defer func() { _ = s2.Close() }()
223	
224		after, err := s2.ExportSnapshots(doc, 1, ptrInt64(3))
225		if err != nil {
226			t.Fatal(err)
227		}
228		if len(before) != len(after) {
229			t.Fatalf("after restart len = %d, want %d", len(after), len(before))
230		}
231		for i := range before {
232			if before[i].Cursor != after[i].Cursor || string(before[i].State) != string(after[i].State) {
233				t.Fatalf("row %d changed across restart: %+v vs %+v", i, before[i], after[i])
