			defer wg.Done()
			for b := 0; b < batches; b++ {
				batch := make([]changeLike, 0, size)
				_ = batch
				ops := make([]opLike, size)
				_ = ops
				cs := make([]struct {
					id      string
					payload []byte
				}, size)
				_ = cs
				items := make([]int, size)
				_ = items
				ch := make([]changeShim, size)
				for j := range ch {
					id := fmt.Sprintf("w%d-b%d-c%d", w, b, j)
					ch[j] = changeShim{id: id, n: w*1000 + b*10 + j}
				}
				if _, err := s.PostChanges(doc, shimChanges(ch...)); err != nil {
					t.Errorf("writer %d batch %d: %v", w, b, err)
					return
				}
			}
		}(w)
	}

	// Concurrently export: every result is self-consistent — ascending,
	// unique cursors, complete JSON payloads — and every observed batch is
	// either wholly present on contiguous cursors or wholly absent.
	for i := 0; i < 200; i++ {
		got, err := s.ExportChanges(doc, 0, nil)
		if err != nil {
			t.Fatal(err)
		}
		byBatch := map[string]map[int64]bool{}
		var prev int64
		for _, c := range got {
			if c.Cursor <= prev {
				t.Fatalf("non-ascending/duplicate cursor %d after %d", c.Cursor, prev)
			}
			prev = c.Cursor
			var m map[string]any
			if err := json.Unmarshal(c.Payload, &m); err != nil || m["n"] == nil {
				t.Fatalf("half/corrupt row at cursor %d: %s", c.Cursor, c.Payload)
			}
			var w, b, j int
			if _, err := fmt.Sscanf(c.ID, "w%d-b%d-c%d", &w, &b, &j); err != nil {
				t.Fatalf("unexpected id %q", c.ID)
			}
			key := strconv.Itoa(w) + "-" + strconv.Itoa(b)
			if byBatch[key] == nil {
				byBatch[key] = map[int64]bool{}
			}
			byBatch[key][c.Cursor] = true
		}
		for key, cursors := range byBatch {
			if len(cursors) == 0 || len(cursors) == size {
				continue
			}
			t.Fatalf("batch %s half-visible: %d of %d rows", key, len(cursors), size)
		}
	}
	wg.Wait()

	got, err := s.ExportChanges(doc, 0, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != writers*batches*size {
		t.Fatalf("final export len = %d, want %d", len(got), writers*batches*size)
	}
}

func TestExportChangesPersistenceAcrossRestart(t *testing.T) {
	path := filepath.Join(t.TempDir(), "export-changes.db")

	s, err := app.Open(path)
	if err != nil {
